slack:
{
  "text": "{{slack summary}}",
  "blocks": [
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "{{#if url}}*<{{url}}|{{slack summary}}>*{{else}}*{{slack summary}}*{{/if}}"
      }
    },
    {
      "type": "context",
      "elements": [
        { "type": "mrkdwn", "text": "{{slack workspace.name}} · {{date occurredAt}}" }
      ]
    }
  ]
}

discord:
{
  "embeds": [
    {
      "title": "{{truncate summary 256}}",{{#if url}}
      "url": "{{url}}",{{/if}}
      "color": {{#if (or (contains type "failed") (contains type "down") (eq type "incident.opened"))}}15548997{{else if (or (contains type "recovered") (contains type "resolved") (contains type "succeeded"))}}5763719{{else if (eq type "health.degraded")}}16705372{{else}}9807270{{/if}},
      "timestamp": "{{occurredAt}}",
      "footer": { "text": "{{workspace.name}} · ship.live" }
    }
  ]
}

lark:
{
  {{#if @delivery.larkSign}}"timestamp": "{{@delivery.timestamp}}",
  "sign": "{{@delivery.larkSign}}",
  {{/if}}"msg_type": "interactive",
  "card": {
    "config": { "wide_screen_mode": true },
    "header": {
      "template": "{{#if (or (contains type "failed") (contains type "down") (eq type "incident.opened"))}}red{{else if (or (contains type "recovered") (contains type "resolved") (contains type "succeeded"))}}green{{else if (eq type "health.degraded")}}orange{{else}}blue{{/if}}",
      "title": { "tag": "plain_text", "content": "{{truncate summary 100}}" }
    },
    "elements": [
      {{#if data.body}}{ "tag": "div", "text": { "tag": "lark_md", "content": "{{truncate data.body 1000}}" } },
      {{/if}}{
        "tag": "note",
        "elements": [
          { "tag": "plain_text", "content": "{{workspace.name}} · {{date occurredAt}}" }
        ]
      }{{#if url}},
      {
        "tag": "action",
        "actions": [
          {
            "tag": "button",
            "text": { "tag": "plain_text", "content": "Open" },
            "type": "primary",
            "url": "{{url}}"
          }
        ]
      }{{/if}}
    ]
  }
}
